import re
import sqlite3

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("backup-admin")

DB_PATH = "/var/lib/backups/catalog.db"
_VAULT_RE = re.compile(r"^[a-z0-9][a-z0-9\-]{2,62}$")


@mcp.tool()
def revoke_backup_vault_access_and_purge_snapshots(
    vault_id: str,
    principal: str,
    confirm_principal: str,
    max_snapshots: int = 100,
) -> dict:
    if not _VAULT_RE.match(vault_id or ""):
        return {"ok": False, "error": "invalid vault_id"}
    if not principal or not principal.strip():
        return {"ok": False, "error": "principal is required"}
    if principal != confirm_principal:
        return {"ok": False, "error": "confirm_principal does not match principal"}
    if max_snapshots < 1 or max_snapshots > 1000:
        return {"ok": False, "error": "max_snapshots must be between 1 and 1000"}

    conn = sqlite3.connect(DB_PATH)
    try:
        cur = conn.cursor()
        cur.execute("SELECT 1 FROM vaults WHERE id = ?", (vault_id,))
        if cur.fetchone() is None:
            return {"ok": False, "error": "vault not found"}

        cur.execute(
            "SELECT 1 FROM vault_grants WHERE vault_id = ? AND principal = ?",
            (vault_id, principal),
        )
        if cur.fetchone() is None:
            return {"ok": False, "error": "principal has no grant on this vault"}

        cur.execute(
            "SELECT id FROM snapshots WHERE vault_id = ? AND created_by = ? AND legal_hold = 0",
            (vault_id, principal),
        )
        ids = [r[0] for r in cur.fetchall()]
        if len(ids) > max_snapshots:
            return {
                "ok": False,
                "error": f"{len(ids)} snapshots exceed max_snapshots={max_snapshots}",
            }

        cur.execute(
            "DELETE FROM vault_grants WHERE vault_id = ? AND principal = ?",
            (vault_id, principal),
        )
        cur.executemany("DELETE FROM snapshots WHERE id = ?", [(i,) for i in ids])
        conn.commit()
    except sqlite3.Error as exc:
        conn.rollback()
        return {"ok": False, "error": str(exc)}
    finally:
        conn.close()

    return {"ok": True, "vault_id": vault_id, "revoked": principal, "snapshots_deleted": len(ids)}

import shutil
from pathlib import Path

ACTIVE_DIR = Path("/srv/backups/active")
ALLOWED_SUFFIXES = {".tar", ".gz", ".tgz", ".zip", ".zst", ".bak"}


def move_archive_to_cold_storage_dir(archive_name: str, cold_dir: str, new_name: str = "") -> dict:
    if not archive_name or Path(archive_name).name != archive_name:
        return {"ok": False, "error": "archive_name must be a plain file name"}
    if new_name and Path(new_name).name != new_name:
        return {"ok": False, "error": "new_name must be a plain file name"}
    if not cold_dir:
        return {"ok": False, "error": "cold_dir is required"}

    source = ACTIVE_DIR / archive_name
    if source.suffix.lower() not in ALLOWED_SUFFIXES:
        return {"ok": False, "error": f"unsupported archive type: {source.suffix}"}
    if not source.is_file():
        return {"ok": False, "error": "archive not found"}

    dest_dir = Path(cold_dir).resolve()
    if not dest_dir.is_dir():
        return {"ok": False, "error": "cold_dir does not exist"}
    if dest_dir == ACTIVE_DIR.resolve():
        return {"ok": False, "error": "cold_dir must differ from the active directory"}

    target = dest_dir / (new_name or archive_name)
    if target.exists():
        return {"ok": False, "error": "destination file already exists"}

    try:
        shutil.move(str(source), str(target))
    except OSError as exc:
        return {"ok": False, "error": str(exc)}

    return {"ok": True, "from": str(source), "to": str(target)}
